import React from 'react';
import { AlertCircle, ArrowRight, User } from 'lucide-react';

const ReportsTab = () => {
  const items = [
    { id: 'R1', title: 'Overflow Bin', citizen: 'John D.', sector: 'Sector 4', status: 'urgent' },
    { id: 'R2', title: 'Illegal Dump', citizen: 'Sarah M.', sector: 'Zone B', status: 'pending' },
  ];

  return (
    <div className="w-full max-w-lg animate-slide-up">
      <h3 className="text-4xl font-black italic text-[#47510B] uppercase tracking-tighter mb-8 px-4">Citizen_Issues<span className="text-[#AB1717]">.</span></h3>

      <div className="space-y-4">
        {items.map((item) => (
          <div key={item.id} className="bg-white p-6 rounded-[40px] border-4 border-[#47510B] flex items-center gap-6 group">
            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${item.status === 'urgent' ? 'bg-[#AB1717] text-white animate-pulse' : 'bg-[#CAD23C] text-[#47510B]'}`}>
              <AlertCircle size={24} />
            </div>
            <div className="flex-1">
              <h4 className="text-lg font-black text-[#47510B] uppercase italic leading-none">{item.title}</h4>
              <p className="text-[10px] font-bold opacity-40 mt-1 uppercase flex items-center gap-2">
                <User size={10} /> {item.citizen} // {item.sector}
              </p>
            </div>
            <button className="text-[#47510B] group-hover:translate-x-2 transition-transform">
              <ArrowRight size={24} strokeWidth={3} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ReportsTab;
